# WhatsApp/Discord, Ansichten, Leads-Pipeline, Buchhaltung mit lexoffice, Wissen/Drive, Scan-Eingang.

AV = {'blue': '#dbeafe', 'peach': '#fde2d4', 'green': '#dcfce7', 'lav': '#ede9fe', 'teal': '#e1f1ed',
      'sand': '#f3ead7', 'rose': '#fde2e7', 'grey': '#e7e9e4'}


def threads(L):
    """Beispiel-Verläufe; L ist das Sprach-Dict mit den lokalisierten Texten je Verlauf."""
    base = [
        # ---------------- Geschäft ----------------
        dict(id='berg', world='business', group='reply', ch='tg', who='Michael Berg', ini='MB', bg=AV['blue'], unread=True),
        dict(id='mendes', world='business', group='reply', ch='tg', who='Carlos Mendes', ini='CM', bg=AV['sand'], unread=True),
        dict(id='weber', world='business', group='fyi', ch='mail', who='Anna Weber', ini='AW', bg=AV['lav'], unread=False),
        dict(id='lenz', world='business', group='wait', ch='wa', who='Julia Lenz', ini='JL', bg=AV['green'], unread=False, waiting=True),
        dict(id='news1', world='business', group='bot', ch='mail', who='Fintech Weekly', ini='FW', bg=AV['grey']),
        dict(id='bot1', world='business', group='bot', ch='tg', who='Signals Bot', ini='SB', bg=AV['grey']),
        dict(id='bot2', world='business', group='bot', ch='dc', who='Devs #releases', ini='DV', bg=AV['grey']),
        # ---------------- Arbeit ----------------
        dict(id='klein', world='work', group='reply', ch='m365', who='Sarah Klein', ini='SK', bg=AV['peach'], unread=True),
        dict(id='nord', world='work', group='fyi', ch='m365', who='Team Nord', ini='TN', bg=AV['teal'], unread=True),
        dict(id='hr', world='work', group='wait', ch='m365', who='Personalabteilung' if L['lang'] == 'de' else 'HR team', ini='HR', bg=AV['rose'], unread=False, waiting=True),
        dict(id='it1', world='work', group='bot', ch='m365', who='IT-Service' if L['lang'] == 'de' else 'IT service', ini='IT', bg=AV['grey']),
        dict(id='it2', world='work', group='bot', ch='m365', who='SharePoint', ini='SP', bg=AV['grey']),
        # ---------------- Privat ----------------
        dict(id='mama', world='private', group='reply', ch='wa', who='Mama', ini='M', bg=AV['rose'], unread=True),
        dict(id='werke', world='private', group='fyi', ch='mail', who='Stadtwerke' if L['lang'] == 'de' else 'City Utilities', ini='SW', bg=AV['sand'], unread=False),
        dict(id='verein', world='private', group='fyi', ch='dc', who='Laufgruppe' if L['lang'] == 'de' else 'Running club', ini='LG', bg=AV['green'], unread=True),
        dict(id='shop', world='private', group='bot', ch='mail', who='Paketdienst' if L['lang'] == 'de' else 'Parcel service', ini='PD', bg=AV['grey']),
    ]
    for t in base:
        t.update(L['t'][t['id']])
    return base


